import { CHAIN, CONTRACTS } from './chain-config.js';
import { SCHEMA_HASH, CONTRACT_REVISION } from '../chain/generated/index.js';

export function assertDeploymentReady(chain = CHAIN, contracts = CONTRACTS) {
  if (chain.deploymentReady !== true || chain.readSchema !== SCHEMA_HASH
    || chain.contractRevision !== CONTRACT_REVISION || !contracts.GAME || !contracts.ADMIN) {
    throw Object.assign(new Error('The next testnet deployment is not ready. Transactions will open after its addresses are verified.'),
      { code: 'DEPLOYMENT_NOT_READY' });
  }
}
